-- Niveau de complexité des textes de la banque (CONF-05), calculé par textComplexity (lib/texts.ts).
-- Les nouveaux textes, originaux, donnent au moins trois textes par niveau et par langue.
UPDATE "texts" SET "complexity" = 'easy' WHERE "title" IN ('Une nuit au camping', 'Le tournoi de soccer', 'The robotics club', 'A night at the campsite', 'The mysterious library');--> statement-breakpoint
